function isMobileViewport() { return window.innerWidth < 860; }

function saveReportNow(unitId, report) {
  S.reports[unitId] = report;
  dataStore.saveReport(unitId, report);
}

/* =============================== Render dispatcher =========================== */
const appEl = document.getElementById("app");

function render() {
  let html = "";
  if (S.view === "login" || !S.currentUser) {
    html = renderLogin();
  } else if (S.view === "dashboard") {
    html = shellWrap(renderDashboard());
  } else if (S.view === "admin-reports") {
    html = shellWrap(renderUnitsOverview());
  } else if (S.view === "units-manage") {
    html = shellWrap(renderDepartmentsManage());
  } else if (S.view === "indicators-manage") {
    html = shellWrap(renderIndicatorsManage());
  } else if (S.view === "goals-manage") {
    html = shellWrap(renderGoalsManage());
  } else if (S.view === "unit-home") {
    html = shellWrap(renderMyUnit());
  } else if (S.view === "unit-report") {
    html = shellWrap(renderUnitReport());
  } else if (S.view === "full-report") {
    html = shellWrap(renderFullReport());
  } else if (S.view === "report-preview") {
    html = shellWrap(renderReportPreview());
  } else {
    html = renderLogin();
  }
  appEl.innerHTML = html;
  afterRender();
}

/* App shell: persistent sidebar wrapper used by every logged-in page ---------- */
function shellWrap(innerHtml) {
  const mobile = isMobileViewport();
  const sidebarOpen = mobile ? S.mobileSidebarOpen : S.sidebarOpen;
  return `
    <div class="app-shell">
      ${sidebarOpen ? renderMainSidebar(mobile) : ""}
      <div class="app-main">
        ${!sidebarOpen ? `<div class="open-sidebar-wrap"><button class="mobile-menu-toggle" data-action="open-sidebar" title="فتح القائمة">${iconMenu()}</button></div>` : ""}
        ${innerHtml}
      </div>
    </div>
  `;
}

const SIDEBAR_PAGES = [
  { id: "dashboard", label: "لوحة المعلومات", group: "الرئيسية" },
  { id: "admin-reports", label: "الأقسام والوحدات", group: "إدارة التقارير" },
  { id: "units-manage", label: "إدارة الأقسام والوحدات", group: "إدارة التقارير" },
  { id: "indicators-manage", label: "إدارة مؤشرات الأداء", group: "إدارة التقارير" },
  { id: "goals-manage", label: "إدارة الأهداف والمستهدفات", group: "إدارة التقارير" },
  { id: "unit-report", label: "مسودة التقرير", group: "التقارير", scope: "unit" },
  { id: "full-report", label: "عرض التقرير كاملاً", group: "التقارير", scope: "unit" },
  { id: "report-preview", label: "معاينة التقرير", group: "التقارير", scope: "unit" },
];
const SIDEBAR_GROUPS = ["الرئيسية", "إدارة التقارير", "التقارير"];

function renderMainSidebar(mobile) {
  const visible = S.isAdmin ? SIDEBAR_PAGES : SIDEBAR_PAGES.filter((p) => p.id === "unit-report" || p.id === "full-report");
  const groupsHtml = SIDEBAR_GROUPS.map((g) => {
    const items = visible.filter((p) => p.group === g);
    if (!items.length) return "";
    return `
      <div>
        <div class="nav-group-label">${esc(g)}</div>
        <div class="nav-list">
          ${items.map((p) => {
            const disabled = p.scope === "unit" && !S.currentUnitId;
            const active = S.view === p.id;
            return `<button class="nav-item ${active ? "active" : ""}" ${disabled ? "disabled" : ""} data-action="nav-to" data-view="${p.id}">${esc(p.label)}</button>`;
          }).join("")}
        </div>
      </div>`;
  }).join("");

  const inner = `
    <div class="sidebar-head">
      <div class="sidebar-head-left">
        <div class="icon-badge">${iconGauge(GOLD)}</div>
        <div class="prs-title sidebar-title">نظام توثيق الأداء</div>
      </div>
      <button class="icon-btn" data-action="${mobile ? "close-mobile-sidebar" : "close-sidebar"}" title="إغلاق القائمة">${iconX()}</button>
    </div>
    <div style="flex:1;display:flex;flex-direction:column;gap:16px;">${groupsHtml}</div>
    <div class="sidebar-sep"></div>
    <button class="logout-btn" data-action="logout">${iconLogout()} تسجيل الخروج</button>
  `;

  if (!mobile) return `<div class="sidebar">${inner}</div>`;
  return `
    <div class="mobile-backdrop" data-action="close-mobile-sidebar"></div>
    <div class="sidebar-mobile-panel"><div class="sidebar" style="margin:0;border-radius:0;height:100vh;max-height:100vh;">${inner}</div></div>
  `;
}

/* =============================== Minimal inline icon set ===================== */
function svgIcon(paths, size, color, strokeWidth) {
  size = size || 16; color = color || "currentColor"; strokeWidth = strokeWidth || 1.9;
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="${color}" stroke-width="${strokeWidth}" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0;display:inline-block;vertical-align:middle">${paths}</svg>`;
}
const iconMenu = (c) => svgIcon(`<line x1="4" y1="7" x2="20" y2="7"/><line x1="4" y1="12" x2="20" y2="12"/><line x1="4" y1="17" x2="20" y2="17"/>`, 17, c);
const iconX = (s, c) => svgIcon(`<line x1="6" y1="6" x2="18" y2="18"/><line x1="6" y1="18" x2="18" y2="6"/>`, s || 14, c || SUBTLE);
const iconLogout = (s, c) => svgIcon(`<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><polyline points="16 17 21 12 16 7"/><line x1="21" y1="12" x2="9" y2="12"/>`, s || 16, c || "#c1594f");
const iconGauge = (c, s) => svgIcon(`<path d="M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z"/><path d="M12 2a10 10 0 0 0-8.66 15L6 15"/><path d="M12 12l4-4"/>`, s || 14, c || GOLD);
const iconBuilding = (c, s) => svgIcon(`<rect x="4" y="2" width="16" height="20" rx="1"/><line x1="9" y1="7" x2="9" y2="7"/><line x1="9" y1="11" x2="9" y2="11"/><line x1="9" y1="15" x2="9" y2="15"/><line x1="15" y1="7" x2="15" y2="7"/><line x1="15" y1="11" x2="15" y2="11"/><line x1="15" y1="15" x2="15" y2="15"/>`, s || 16, c || ROSE);
const iconPlus = (s, c) => svgIcon(`<line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/>`, s || 15, c);
const iconTrash = (s, c) => svgIcon(`<polyline points="3 6 5 6 21 6"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/><path d="M10 11v6"/><path d="M14 11v6"/><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"/>`, s || 14, c || "#c1594f");
const iconPencil = (s, c) => svgIcon(`<path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/>`, s || 14, c || INK);
const iconPower = (s, c) => svgIcon(`<path d="M12 2v10"/><path d="M18.4 6.6a9 9 0 1 1-12.8 0"/>`, s || 14, c);
const iconChevronLeft = (s, c) => svgIcon(`<polyline points="15 18 9 12 15 6"/>`, s || 14, c || SUBTLE);
const iconChevronRight = (s, c) => svgIcon(`<polyline points="9 18 15 12 9 6"/>`, s || 14, c || SUBTLE);
const iconChevronDown = (s, c) => svgIcon(`<polyline points="6 9 12 15 18 9"/>`, s || 14, c);
const iconChevronUp = (s, c) => svgIcon(`<polyline points="18 15 12 9 6 15"/>`, s || 14, c);
const iconArrowRight = (s, c) => svgIcon(`<line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/>`, s || 17, c || INK);
const iconCheck = (s, c) => svgIcon(`<polyline points="20 6 9 17 4 12"/>`, s || 16, c);
const iconCheckCircle = (s, c) => svgIcon(`<path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>`, s || 14, c);
const iconCircle = (s, c) => svgIcon(`<circle cx="12" cy="12" r="9"/>`, s || 14, c);
const iconEye = (s, c) => svgIcon(`<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>`, s || 16, c || SUBTLE);
const iconEyeOff = (s, c) => svgIcon(`<path d="M17.94 17.94A10.94 10.94 0 0 1 12 20c-7 0-11-8-11-8a18.5 18.5 0 0 1 4.22-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/>`, s || 16, c || SUBTLE);
const iconUser = (s, c) => svgIcon(`<path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>`, s || 16, c || SUBTLE);
const iconLogin = (s, c) => svgIcon(`<path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/>`, s || 17, c);
const iconSave = (s, c) => svgIcon(`<path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/>`, s || 15, c);
const iconPrinter = (s, c) => svgIcon(`<polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/>`, s || 15, c);
const iconLayers = (s, c) => svgIcon(`<polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/>`, s || 16, c || ROSE);
const iconSparkles = (s, c) => svgIcon(`<path d="M12 3l1.5 4.5L18 9l-4.5 1.5L12 15l-1.5-4.5L6 9l4.5-1.5L12 3z"/>`, s || 15, c);
const ICONS_BY_SECTION = {}; // not needed for section icons; use a generic dot instead

function fieldWrap(label, requiredOrHtml, maybeHtml) {
  let required = false, inner;
  if (typeof maybeHtml === "undefined") { inner = requiredOrHtml; } else { required = !!requiredOrHtml; inner = maybeHtml; }
  return `<div class="field"><label class="field-label">${esc(label)} ${required ? '<span class="req-star">*</span>' : ""}</label>${inner}</div>`;
}
function selectHtml(name, value, options, placeholder, extraAttrs) {
  extraAttrs = extraAttrs || "";
  const opts = options.map((o) => `<option value="${esc(o)}" ${o === value ? "selected" : ""}>${esc(o)}</option>`).join("");
  return `<select class="input" data-field="${esc(name)}" ${extraAttrs}><option value="">${esc(placeholder || "اختاري")}</option>${opts}</select>`;
}
function radioGroupHtml(name, value, options) {
  return `<div class="radio-group" data-radio-group="${esc(name)}">${options.map((o) =>
    `<button type="button" class="radio-pill ${o === value ? "active" : ""}" data-action="set-radio" data-radio-group="${esc(name)}" data-value="${esc(o)}">${esc(o)}</button>`
  ).join("")}</div>`;
}
function pillBtn(label, opts) {
  opts = opts || {};
  const variant = opts.variant || "primary";
  const cls = { primary: "pill-primary", ghost: "pill-ghost", soft: "pill-soft", danger: "pill-danger" }[variant];
  const icon = opts.icon || "";
  const attrs = Object.entries(opts.data || {}).map(([k, v]) => `data-${k}="${esc(v)}"`).join(" ");
  return `<button type="${opts.type || "button"}" class="pill-btn ${cls}" ${opts.disabled ? "disabled" : ""} data-action="${esc(opts.action || "")}" ${attrs}>${icon}${esc(label)}</button>`;
}
function topBarHtml({ title, subtitle, backAction, right }) {
  return `
    <div class="topbar">
      <div class="topbar-left">
        ${backAction ? `<button class="back-btn" data-action="${backAction}">${iconArrowRight()}</button>` : ""}
        <div>
          <div class="prs-title topbar-title">${esc(title)}</div>
          ${subtitle ? `<div class="topbar-subtitle">${esc(subtitle)}</div>` : ""}
        </div>
      </div>
      ${right ? `<div class="topbar-right">${right}</div>` : ""}
    </div>`;
}
function progressBarHtml(percent, color) {
  return `<div class="progress-bar"><div class="progress-bar-fill" style="width:${percent}%;background:${color || ROSE}"></div></div>`;
}
function badgeHtml(label, color, bg) {
  return `<span class="badge" style="color:${color};background:${bg}">${esc(label)}</span>`;
}

/* =============================== Login ======================================= */
function renderLogin() {
  const err = S.ui.loginError || "";
  const showPw = !!S.ui.loginShowPw;
  return `
  <div class="login-wrap">
    <div class="login-box">
      <div class="login-card">
        <div style="text-align:center;margin-bottom:26px;">
          <img class="login-logo" src="${ASSOCIATION_LOGO}" alt="جمعية فرقان" />
          <div class="prs-title" style="font-size:20px;font-weight:900;">نظام توثيق الأداء</div>
          <div style="font-size:12px;color:${SUBTLE};margin-top:6px;">تسجيل الدخول للمتابعة</div>
        </div>
        <form id="login-form">
          ${fieldWrap("اسم المستخدم", true, `
            <div class="input-icon-wrap">
              <span class="input-icon-right">${iconUser()}</span>
              <input class="input" style="padding-right:38px" id="login-username" placeholder="اسم المستخدم" required />
            </div>`)}
          ${fieldWrap("كلمة السر", true, `
            <div class="input-icon-wrap">
              <input class="input" style="padding-left:38px" id="login-password" type="${showPw ? "text" : "password"}" placeholder="كلمة السر" required />
              <button type="button" class="input-icon-left-btn" data-action="toggle-login-pw">${showPw ? iconEyeOff() : iconEye()}</button>
            </div>`)}
          ${err ? `<div class="error-box">${esc(err)}</div>` : ""}
          <button type="submit" class="submit-btn">${iconLogin(17, "#fff")} تسجيل الدخول</button>
        </form>
      </div>
      <div class="login-hint">بيانات تجريبية للاختبار — مديرة النظام: admin / admin123 — موظفة وحدة: unit1 / 1234</div>
    </div>
  </div>`;
}

function handleLoginSubmit() {
  const username = document.getElementById("login-username").value.trim();
  const password = document.getElementById("login-password").value;
  const match = MOCK_USERS.find((u) => u.username === username && u.password === password);
  if (!match) { S.ui.loginError = "اسم المستخدم أو كلمة السر غير صحيحة"; render(); return; }
  S.ui.loginError = "";
  doLogin(match);
}

function doLogin(user) {
  S.currentUser = user;
  S.isAdmin = user.role === "admin";
  S.units = dataStore.getUnits();
  S.departments = dataStore.getDepartments();
  S.indicatorDefinitions = dataStore.getIndicatorDefinitions();
  S.goalsDefinitions = dataStore.getGoalsDefinitions();
  S.sidebarOpen = !isMobileViewport();
  if (S.isAdmin) {
    const reports = {};
    S.units.forEach((u) => { reports[u.id] = dataStore.getReport(u.id); });
    S.reports = reports;
    S.view = "dashboard";
  } else {
    const unitId = user.unitId;
    S.reports[unitId] = dataStore.getReport(unitId);
    S.currentUnitId = unitId;
    S.view = "unit-home";
  }
  render();
}

function doLogout() {
  S.currentUser = null; S.currentUnitId = null; S.view = "login"; S.ui = {};
  render();
}

/* =============================== Dashboard (admin) =========================== */
function statCardHtml(label, value, color) {
  return `<div class="stat-card"><div class="value" style="color:${color}">${esc(value)}</div><div class="label">${esc(label)}</div></div>`;
}

function renderDashboard() {
  const activeUnits = S.units.filter((u) => u.status === "active");
  let totalCompleted = 0, totalSections = 0;
  const allIndicators = [], allGoals = [];
  activeUnits.forEach((u) => {
    const report = S.reports[u.id] || emptyReport();
    const p = computeProgress(report);
    totalCompleted += p.completed; totalSections += p.total;
    (report.sections?.kpi?.data?.indicators || []).filter((r) => r.name && r.name.trim()).forEach((ind) => allIndicators.push({ ...ind, unitName: u.name }));
    (report.sections?.goals?.data?.goals || []).forEach((g) => {
      (g.operationalGoals || []).forEach((og) => allGoals.push({ ...og, unitName: u.name, strategicGoal: g.strategicGoal }));
    });
  });
  const overallPct = totalSections ? Math.round((totalCompleted / totalSections) * 100) : 0;
  const avgGoalPct = allGoals.length ? Math.round(allGoals.reduce((s, g) => s + (Number(g.percentage) || 0), 0) / allGoals.length) : 0;
  const unitBarData = activeUnits.map((u) => ({ name: u.name, percent: computeProgress(S.reports[u.id] || emptyReport()).percent }));

  const barsHtml = unitBarData.length === 0
    ? `<div style="font-size:12.5px;color:${SUBTLE}">لا توجد وحدات بعد.</div>`
    : `<div class="chart-wrap">${unitBarData.map((d) => `
        <div class="bar-chart-row">
          <div class="bar-chart-label" title="${esc(d.name)}">${esc(d.name)}</div>
          <div class="bar-chart-track"><div class="bar-chart-fill" style="width:${d.percent}%;background:${ROSE}"></div></div>
          <div class="bar-chart-value">${d.percent}٪</div>
        </div>`).join("")}</div>`;

  const indicatorsRows = allIndicators.map((ind) => {
    const target = Number(ind.target) || 0, actual = Number(ind.actual) || 0;
    const pct = target > 0 ? Math.round((actual / target) * 100) : 0;
    const color = pct >= 100 ? GREEN : pct >= 60 ? GOLD : DANGER;
    return `<tr><td style="color:${SUBTLE}">${esc(ind.unitName)}</td><td style="font-weight:600">${esc(ind.name)}</td><td style="text-align:center">${esc(target)}</td><td style="text-align:center">${esc(actual)}</td><td style="text-align:center;font-weight:800;color:${color}">${pct}٪</td></tr>`;
  }).join("");

  const goalsRows = allGoals.map((g) => {
    const meta = goalLevelMeta(g.level);
    return `<tr><td style="color:${SUBTLE}">${esc(g.unitName)}</td><td style="font-weight:600">${esc(g.name)}</td><td style="text-align:center">${g.level ? badgeHtml(g.level, meta.color, meta.bg) : "—"}</td><td style="text-align:center;font-weight:800;color:${meta.color}">${g.percentage !== "" ? g.percentage + "٪" : "—"}</td></tr>`;
  }).join("");

  return `
  <div class="page-wrap"><div class="page-inner">
    ${topBarHtml({ title: "لوحة المعلومات", subtitle: `مرحبًا ${esc(S.currentUser.name)} — نظرة شاملة على كل الوحدات`,
      right: pillBtn("الأقسام والوحدات", { icon: iconLayers(15, "#fff"), action: "nav-to", data: { view: "admin-reports" } }) + pillBtn("خروج", { variant: "danger", icon: iconLogout(15, DANGER), action: "logout" }) })}
    <div class="stat-grid">
      ${statCardHtml("عدد الوحدات", activeUnits.length, ROSE)}
      ${statCardHtml("نسبة الإنجاز الكلية", overallPct + "٪", overallPct === 100 ? GREEN : ROSE)}
      ${statCardHtml("عدد مؤشرات الأداء", allIndicators.length, GOLD)}
      ${statCardHtml("عدد الأهداف التشغيلية", allGoals.length, GREEN)}
    </div>
    <div class="card" style="margin-bottom:18px;">
      <div class="prs-title" style="font-size:14px;font-weight:800;margin-bottom:12px;">نسبة الإنجاز حسب الوحدة</div>
      ${barsHtml}
    </div>
    <div class="card" style="margin-bottom:18px;">
      <div class="prs-title" style="font-size:14px;font-weight:800;margin-bottom:12px;">مؤشرات الأداء — كل الوحدات</div>
      ${allIndicators.length === 0 ? `<div style="font-size:12.5px;color:${SUBTLE}">لا توجد مؤشرات مُدخلة بعد.</div>` : `
      <div class="table-wrap"><table class="prs-table"><thead><tr style="background:${GOLD_BG}">
        <th style="color:#8a6a2f">الوحدة</th><th style="color:#8a6a2f">المؤشر</th><th style="text-align:center;color:#8a6a2f">المستهدف</th><th style="text-align:center;color:#8a6a2f">المتحقق</th><th style="text-align:center;color:#8a6a2f">النسبة</th>
      </tr></thead><tbody>${indicatorsRows}</tbody></table></div>`}
    </div>
    <div class="card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
        <div class="prs-title" style="font-size:14px;font-weight:800;">الأهداف التشغيلية — كل الوحدات</div>
        <span style="font-size:11px;color:${SUBTLE}">متوسط النسبة: ${avgGoalPct}٪</span>
      </div>
      ${allGoals.length === 0 ? `<div style="font-size:12.5px;color:${SUBTLE}">لا توجد أهداف مُدخلة بعد.</div>` : `
      <div class="table-wrap"><table class="prs-table"><thead><tr style="background:${DANGER_BG}">
        <th style="color:${ROSE_DARK}">الوحدة</th><th style="color:${ROSE_DARK}">الهدف التشغيلي</th><th style="text-align:center;color:${ROSE_DARK}">المستوى</th><th style="text-align:center;color:${ROSE_DARK};width:70px">النسبة</th>
      </tr></thead><tbody>${goalsRows}</tbody></table></div>`}
    </div>
  </div></div>`;
}

/* =============================== Units overview (admin) ====================== */
function unitCardHtml(unit, department, report) {
  const p = computeProgress(report);
  const overall = p.total > 0 && p.completed === p.total ? "completed" : (p.completed > 0 || p.drafted > 0) ? "draft" : "not_started";
  const meta = statusMeta(overall);
  return `
  <div class="card prs-card">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px;">
      <div>
        <div style="font-size:14.5px;font-weight:800;">${esc(unit.name)}</div>
        ${department ? `<div style="font-size:11px;color:${SUBTLE};margin-top:2px;">${esc(department.name)}</div>` : ""}
      </div>
      <div style="width:34px;height:34px;border-radius:10px;background:${DANGER_BG};display:flex;align-items:center;justify-content:center;flex-shrink:0;">${iconBuilding(ROSE, 16)}</div>
    </div>
    <div style="border-top:1px solid ${BORDER};padding-top:10px;display:flex;align-items:center;justify-content:space-between;">
      <button data-action="open-unit" data-unit-id="${esc(unit.id)}" style="display:flex;align-items:center;gap:4px;background:none;border:none;cursor:pointer;color:${ROSE};font-size:12.5px;font-weight:700;padding:0;">${iconChevronLeft(14, ROSE)} التقرير</button>
      ${badgeHtml(meta.label, meta.color, meta.bg)}
    </div>
  </div>`;
}

function renderUnitsOverview() {
  const activeDepartments = S.departments.filter((d) => d.status === "active");
  const sections = activeDepartments.map((dept) => {
    const units = S.units.filter((u) => u.departmentId === dept.id && u.status === "active");
    return `
    <div class="card card-lg" style="margin-bottom:16px;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">
        <div><div style="font-size:16px;font-weight:800;">${esc(dept.name)}</div><div style="font-size:11.5px;color:${SUBTLE};margin-top:2px;">${units.length} وحدة</div></div>
        <div style="width:40px;height:40px;border-radius:12px;background:${DANGER_BG};display:flex;align-items:center;justify-content:center;">${iconLayers(19, ROSE)}</div>
      </div>
      ${units.length === 0 ? `<div style="font-size:12px;color:${SUBTLE};padding:10px 2px;">لا توجد وحدات في هذا القسم بعد.</div>` :
        `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;">${units.map((u) => unitCardHtml(u, dept, S.reports[u.id] || emptyReport())).join("")}</div>`}
    </div>`;
  }).join("");

  const unassigned = S.units.filter((u) => u.status === "active" && !S.departments.some((d) => d.id === u.departmentId && d.status === "active"));
  const unassignedHtml = unassigned.length ? `
    <div class="card card-lg">
      <div style="font-size:16px;font-weight:800;margin-bottom:16px;">وحدات بدون قسم</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:12px;">${unassigned.map((u) => unitCardHtml(u, null, S.reports[u.id] || emptyReport())).join("")}</div>
    </div>` : "";

  return `
  <div class="page-wrap"><div class="page-inner">
    ${topBarHtml({ title: "الأقسام والوحدات", subtitle: `مرحبًا ${esc(S.currentUser.name)}`,
      right: pillBtn("إدارة الأقسام والوحدات", { icon: iconBuilding("#fff", 15), action: "nav-to", data: { view: "units-manage" } }) +
             pillBtn("إدارة المؤشرات", { variant: "ghost", icon: iconGauge(INK, 15), action: "nav-to", data: { view: "indicators-manage" } }) +
             pillBtn("إدارة الأهداف", { variant: "ghost", icon: iconLayers(15, INK), action: "nav-to", data: { view: "goals-manage" } }) +
             pillBtn("خروج", { variant: "danger", icon: iconLogout(15, DANGER), action: "logout" }) })}
    ${sections}${unassignedHtml}
    ${activeDepartments.length === 0 && unassigned.length === 0 ? `<div class="card" style="text-align:center;color:${SUBTLE};padding:36px;">لا توجد أقسام أو وحدات بعد — أضيفيها من "إدارة الأقسام والوحدات".</div>` : ""}
  </div></div>`;
}

/* =============================== My unit (unit-level user landing) =========== */
function renderMyUnit() {
  const unit = S.units.find((u) => u.id === S.currentUnitId);
  if (!unit) return `<div class="page-wrap">تعذر إيجاد الوحدة.</div>`;
  const report = S.reports[unit.id] || emptyReport();
  return `
  <div class="page-wrap"><div class="page-inner" style="max-width:640px;">
    <div class="prs-title" style="font-size:20px;font-weight:900;margin-bottom:4px;">مرحبًا بك</div>
    <div style="font-size:12px;color:${SUBTLE};margin-bottom:22px;">افتحي تقرير وحدتك من البطاقة أدناه</div>
    ${unitCardHtml(unit, null, report).replace('data-action="open-unit"', `data-action="open-unit" data-unit-id="${esc(unit.id)}"`)}
  </div></div>`;
}

