/* =============================== Full report + preview (read view) ============ */
function kv(label, value) {
  if (value === undefined || value === null || value === "") return "";
  return `<span>${esc(label)}: <b>${esc(value)}</b></span>`;
}
function kvBlock(pairs) {
  const html = pairs.filter(Boolean).join("");
  return html ? `<div class="doc-kv">${html}</div>` : "";
}
function textBlock(label, value) {
  if (!value) return "";
  return `<div style="margin-bottom:8px;"><div style="font-size:11px;color:${SUBTLE};font-weight:700;">${esc(label)}</div><div style="font-size:12.5px;">${esc(value)}</div></div>`;
}

function sectionReportHtml(section, saved, report) {
  const d = (saved && saved.data) || {};
  const meta = statusMeta(saved ? saved.status : "not_started");
  const head = `<div class="doc-section-title">${esc(section.label)} ${badgeHtml(meta.label, meta.color, meta.bg)}</div>`;
  let body = "";

  if (section.id === "basic") {
    body = kvBlock([kv("الجهة الرئيسية", d.mainEntity), kv("الجهة التي ترفع التقرير", d.reportingEntityType), kv("اسم الجهة", d.entityName), kv("اسم المكتب", d.officeName),
      kv("الفترة", d.periodType), kv("من", d.startDate), kv("إلى", d.endDate), kv("العام الهجري", d.hijriYear), kv("الشهر", d.month), kv("الفصل", d.term)]) +
      kvBlock([kv("معدّة التقرير", d.preparerName), kv("المسمى الوظيفي", d.preparerTitle), kv("الرئيسة المباشرة", d.managerName)]);
  } else if (section.id === "kpi") {
    const rows = (d.indicators || []).filter((r) => r.name).map((row) => {
      const def = S.indicatorDefinitions.find((x) => x.name === row.name);
      const resolved = resolveIndicatorRow(row, def);
      const status = def ? computeIndicatorStatus(resolved) : { emoji: "⚪", label: "—", color: SUBTLE };
      const target = def && def.target !== "" ? def.target : "—";
      return `<div class="bar-chart-row"><div class="bar-chart-label" style="width:170px" title="${esc(row.name)}">${esc(row.name)}</div>
        <div class="bar-chart-track"><div class="bar-chart-fill" style="width:${Math.min(100, resolved.ratio ? resolved.ratio * 100 : 0)}%;background:${status.color}"></div></div>
        <div class="bar-chart-value" style="width:auto;white-space:nowrap;">${esc(row.actual || "—")}/${esc(target)} ${status.emoji}</div></div>`;
    }).join("");
    body = rows ? `<div class="chart-wrap">${rows}</div>` : `<div class="hint">لا توجد مؤشرات مُدخلة.</div>`;
  } else if (section.id === "goals") {
    const rows = (d.goals || []).map((g) => (g.operationalGoals || []).map((og) => {
      const gm = goalLevelMeta(og.level);
      return `<div style="margin-bottom:8px;"><div style="font-size:12.5px;"><b>${esc(og.name)}</b> — ${esc(g.strategicGoal)}</div>
        <div class="doc-kv">${kv("المستوى", og.level)} ${kv("النسبة", og.percentage !== "" ? og.percentage + "٪" : "")} ${kv("الدليل", og.evidenceType)}</div>
        ${og.explanation ? `<div style="font-size:11.5px;color:${SUBTLE}">${esc(og.explanation)}</div>` : ""}</div>`;
    }).join("")).join("");
    body = rows || `<div class="hint">لا توجد أهداف مُدخلة.</div>`;
  } else if (section.id === "programs") {
    body = (d.programs || []).map((p) => `<div style="margin-bottom:12px;"><div style="font-size:13px;font-weight:800;">${esc(p.name || "(بدون اسم)")}</div>
      ${kvBlock([kv("النوع", p.workType), kv("الفئة", p.targetGroup), kv("المستهدف", p.targetCount), kv("الفعلي", p.actualBeneficiaries), kv("الحالة", p.executionStatus), kv("نسبة الحضور", p.attendanceRate)])}
      ${textBlock("أبرز نتيجة", p.highlightResult)}</div>`).join("") || `<div class="hint">لا توجد أعمال مُدخلة.</div>`;
  } else if (section.id === "tools") {
    body = (d.tools || []).map((t) => `<div style="margin-bottom:12px;"><div style="font-size:13px;font-weight:800;">${esc(t.name || "(بدون اسم)")}</div>
      ${kvBlock([kv("النوع", t.toolType), kv("حجم العينة", t.sampleSize), kv("المستجيبات", t.respondentsCount), kv("نسبة الاستجابة", computeResponseRate(t.sampleSize, t.respondentsCount) != null ? computeResponseRate(t.sampleSize, t.respondentsCount) + "٪" : ""), kv("الجودة", t.resultQuality)])}</div>`).join("") || `<div class="hint">لا توجد أدوات مُدخلة.</div>`;
  } else if (section.id === "analysis") {
    body = textBlock("أبرز نتيجة إيجابية", d.positiveResult) + textBlock("تفسيرها", d.positiveInterpretation) +
      textBlock("أبرز نتيجة تحتاج تحسين", d.improvementResult) + textBlock("الإجراء المقترح", d.improvementAction) +
      (d.comparisons || []).map((c) => kvBlock([kv("الموضوع", c.topic), kv("النتيجة", c.resultValue), kv("الحكم", c.judgment), kv("السبب", c.changeReason)])).join("") +
      textBlock("الخلاصة التحليلية", d.summary);
  } else if (section.id === "strengths") {
    body = (d.strengths || []).map((s) => `<div style="margin-bottom:10px;"><b>${esc(s.name)}</b> ${kvBlock([kv("المجال", s.area), kv("الاستمرارية", s.continuity)])}${textBlock("الوصف", s.description)}</div>`).join("") || `<div class="hint">لا توجد نقاط قوة مُدخلة.</div>`;
  } else if (section.id === "challenges") {
    body = (d.challenges || []).map((c) => `<div style="margin-bottom:10px;"><b>${esc(c.name)}</b> ${kvBlock([kv("المجال", c.area), kv("المستوى", c.severity), kv("النطاق", c.scope)])}${textBlock("الوصف", c.description)}</div>`).join("") || `<div class="hint">لا توجد صعوبات مُدخلة.</div>`;
  } else if (section.id === "improvement") {
    body = (d.opportunities || []).map((o) => `<div style="margin-bottom:10px;"><b>${esc(o.name)}</b> ${kvBlock([kv("المجال", o.field), kv("الأولوية", o.priority), kv("السهولة", o.ease)])}</div>`).join("") || `<div class="hint">لا توجد فرص تحسين مُدخلة.</div>`;
  } else if (section.id === "initiatives") {
    body = (d.initiatives || []).map((it) => `<div style="margin-bottom:10px;"><b>${esc(it.name)}</b> ${kvBlock([kv("النوع", it.entryType), kv("المرحلة", it.stage), kv("المستفيدات", it.beneficiariesCount)])}</div>`).join("") || `<div class="hint">لا توجد مبادرات مُدخلة.</div>`;
  } else {
    body = textBlock("المحتوى", d.content) || `<div class="hint">لم يُدخل محتوى بعد.</div>`;
  }
  if (d.notes) body += textBlock("ملاحظات", d.notes);
  return `<div class="doc-section">${head}${body}</div>`;
}

function fullReportOrPreviewBody(unit, report) {
  return SECTIONS.map((section) => sectionReportHtml(section, report.sections?.[section.id], report)).join("");
}

function renderFullReport() {
  const unit = S.units.find((u) => u.id === S.currentUnitId);
  const report = S.reports[unit.id] || emptyReport();
  const progress = computeProgress(report);
  return `
  <div class="page-wrap"><div class="page-inner report">
    ${topBarHtml({ title: "عرض التقرير كاملاً", subtitle: `${unit.name} — ${progress.completed} من ${progress.total} أقسام مكتملة`, backAction: "nav-to-unit-report",
      right: pillBtn("معاينة الطباعة", { variant: "ghost", icon: iconPrinter(15, INK), action: "nav-to", data: { view: "report-preview" } }) })}
    <div class="card card-lg">${fullReportOrPreviewBody(unit, report)}</div>
    <div class="hint" style="margin-top:12px;">للتعديل على أي قسم، ارجعي إلى "مسودة التقرير" واختاري القسم من قائمة المراحل.</div>
  </div></div>`;
}

function renderReportPreview() {
  const unit = S.units.find((u) => u.id === S.currentUnitId);
  const report = S.reports[unit.id] || emptyReport();
  const shared = report.shared || {};
  return `
  <div class="page-wrap"><div class="page-inner report">
    <div class="no-print">${topBarHtml({ title: "معاينة التقرير", backAction: "nav-to-unit-report", right: pillBtn("طباعة", { icon: iconPrinter(15, "#fff"), action: "print-page" }) })}</div>
    <div class="doc-page">
      <div style="text-align:center;margin-bottom:22px;">
        <img src="${ASSOCIATION_LOGO}" alt="شعار الجمعية" style="width:74px;margin:0 auto 10px;display:block;" />
        <div class="prs-doc-title" style="font-size:20px;font-weight:800;">التقرير الدوري للأداء</div>
        <div class="prs-doc" style="font-size:13px;color:${SUBTLE};margin-top:4px;">${esc(unit.name)} ${shared.periodType ? "— " + esc(shared.periodType) : ""} ${shared.hijriYear ? esc(shared.hijriYear) : ""}</div>
      </div>
      ${fullReportOrPreviewBody(unit, report)}
      <div style="text-align:center;font-size:10.5px;color:${SUBTLE};margin-top:10px;">أُعِد بواسطة: ${esc(shared.preparerName || "—")} — ${esc(shared.preparerTitle || "")}</div>
    </div>
  </div></div>`;
}

/* =============================== Live-computed field patches (no full render) = */
function liveUpdateComputed(el) {
  const field = el.dataset.field;
  if (field === "summary" || field === "explanation") {
    const wrap = el.closest(".field");
    const box = wrap && wrap.querySelector(".char-count");
    if (box) box.textContent = `${el.value.length} / ${field === "summary" ? 500 : 300}`;
  } else if (field === "sampleSize" || field === "respondentsCount") {
    const item = el.closest(".repeat-item");
    if (!item) return;
    const sampleEl = item.querySelector('[data-field="sampleSize"]');
    const respEl = item.querySelector('[data-field="respondentsCount"]');
    const rate = computeResponseRate(sampleEl ? sampleEl.value : "", respEl ? respEl.value : "");
    const box = item.querySelector(".readonly-box");
    if (box) box.textContent = rate != null ? `${rate}٪` : "تُحسب تلقائيًا بعد إدخال حجم العينة وعدد المستجيبات";
  }
}

/* =============================== Input / change delegation ==================== */
function attachFormListeners() {
  appEl.addEventListener("input", (e) => {
    const el = e.target;
    if (el.dataset && el.dataset.field && el.tagName !== "SELECT") {
      setFieldFromEl(el);
      liveUpdateComputed(el);
    } else if (el.dataset && el.dataset.newind) {
      const key = `newIndicatorForm_${el.dataset.newind}`;
      (S.ui[key] = S.ui[key] || {})[el.dataset.newindField] = el.value;
    } else if (el.dataset && el.dataset.expandableOther) {
      (S.ui.expandableOtherText = S.ui.expandableOtherText || {})[el.dataset.expandableOther] = el.value;
    }
  });

  appEl.addEventListener("change", (e) => {
    const el = e.target;
    if (el.tagName === "SELECT" && el.dataset && el.dataset.field) {
      setFieldFromEl(el);
      if (el.dataset.field === "level" && el.dataset.subarr === "operationalGoals") {
        const list = getItemList(el.dataset.arr);
        const item = findById(list, el.dataset.id);
        const sub = item && findById(item[el.dataset.subarr] || [], el.dataset.subid);
        if (sub) sub.percentage = GOAL_LEVEL_PERCENTAGE[el.value] ?? "";
      }
      if (el.dataset.field === "evidenceType" && el.dataset.subarr === "operationalGoals") {
        const list = getItemList(el.dataset.arr);
        const item = findById(list, el.dataset.id);
        const sub = item && findById(item[el.dataset.subarr] || [], el.dataset.subid);
        if (sub) sub.evidenceAnswer = "";
      }
      render();
      return;
    }
    if (el.dataset && el.dataset.newind) {
      const key = `newIndicatorForm_${el.dataset.newind}`;
      (S.ui[key] = S.ui[key] || {})[el.dataset.newindField] = el.value;
      render();
      return;
    }
    if (el.dataset && el.dataset.action === "assign-unit-dept") {
      const u = S.units.find((x) => x.id === el.dataset.id);
      if (u) { u.departmentId = el.value; dataStore.saveUnits(S.units); }
      render();
      return;
    }
  });

  document.body.addEventListener("submit", (e) => {
    if (e.target && e.target.id === "login-form") { e.preventDefault(); handleLoginSubmit(); }
  });

  window.addEventListener("resize", () => {
    clearTimeout(window.__prsResizeT);
    window.__prsResizeT = setTimeout(() => { if (S.currentUser) render(); }, 150);
  });
}

/* =============================== Click delegation (all data-action) =========== */
function attachClickListener() {
  appEl.addEventListener("click", (e) => {
    // Custom radio pills (both generic set-radio and item-bound set-item-radio)
    const radioBtn = e.target.closest('[data-action="set-item-radio"]');
    if (radioBtn) {
      const ds = radioBtn.dataset;
      const fakeEl = { dataset: ds, value: ds.value };
      setFieldFromEl(fakeEl);
      render();
      return;
    }
    const newindRadio = e.target.closest('[data-action="set-newind-radio"]');
    if (newindRadio) {
      const ds = newindRadio.dataset;
      const key = `newIndicatorForm_${ds.newind}`;
      (S.ui[key] = S.ui[key] || {})[ds.newindField] = ds.value;
      render();
      return;
    }

    const btn = e.target.closest("[data-action]");
    if (!btn) return;
    const action = btn.dataset.action;
    const ds = btn.dataset;

    switch (action) {
      /* ---------- navigation & shell ---------- */
      case "nav-to": S.view = ds.view; if (ds.view !== "unit-report") S.activeSectionId = null; if (isMobileViewport()) S.mobileSidebarOpen = false; render(); break;
      case "nav-back-admin": S.view = "admin-reports"; render(); break;
      case "nav-back-from-report": S.view = S.isAdmin ? "admin-reports" : "unit-home"; S.activeSectionId = null; render(); break;
      case "nav-to-unit-report": S.view = "unit-report"; render(); break;
      case "open-sidebar": if (isMobileViewport()) S.mobileSidebarOpen = true; else S.sidebarOpen = true; render(); break;
      case "close-sidebar": S.sidebarOpen = false; render(); break;
      case "close-mobile-sidebar": S.mobileSidebarOpen = false; render(); break;
      case "logout": doLogout(); break;
      case "print-page": window.print(); break;

      /* ---------- units overview ---------- */
      case "open-unit": {
        const unitId = ds.unitId;
        if (!S.reports[unitId]) S.reports[unitId] = dataStore.getReport(unitId);
        S.currentUnitId = unitId; S.view = "unit-report"; S.openPhaseId = null; S.activeSectionId = null; render();
        break;
      }

      /* ---------- departments management ---------- */
      case "add-department": {
        const nameEl = document.getElementById("new-dept-name");
        const name = (nameEl.value || "").trim();
        if (!name) break;
        S.departments = [...S.departments, { id: uid("dept"), name, status: "active", createdAt: Date.now() }];
        dataStore.saveDepartments(S.departments);
        S.ui.newDeptName = "";
        render();
        break;
      }
      case "toggle-department": {
        S.departments = S.departments.map((d) => d.id === ds.id ? { ...d, status: d.status === "active" ? "disabled" : "active" } : d);
        dataStore.saveDepartments(S.departments); render();
        break;
      }
      case "start-dept-edit": S.ui.editingDeptId = ds.id; S.ui.editDeptValue = ds.name; render(); break;
      case "cancel-dept-edit": S.ui.editingDeptId = null; render(); break;
      case "save-dept-edit": {
        const val = document.getElementById("edit-dept-name").value.trim();
        if (val) { S.departments = S.departments.map((d) => d.id === ds.id ? { ...d, name: val } : d); dataStore.saveDepartments(S.departments); }
        S.ui.editingDeptId = null; render();
        break;
      }

      /* ---------- units management ---------- */
      case "add-unit": {
        const name = (document.getElementById("new-unit-name").value || "").trim();
        const deptId = document.getElementById("new-unit-dept").value;
        if (!name) break;
        S.units = [...S.units, { id: uid("unit"), name, status: "active", departmentId: deptId || "", createdAt: Date.now() }];
        dataStore.saveUnits(S.units);
        S.ui.newUnitName = ""; S.ui.newUnitDept = "";
        render();
        break;
      }
      case "start-unit-edit": S.ui.editingUnitId = ds.id; S.ui.editUnitValue = ds.name; render(); break;
      case "cancel-unit-edit": S.ui.editingUnitId = null; render(); break;
      case "save-unit-edit": {
        const val = document.getElementById("edit-unit-name").value.trim();
        if (val) { S.units = S.units.map((u) => u.id === ds.id ? { ...u, name: val } : u); dataStore.saveUnits(S.units); }
        S.ui.editingUnitId = null; render();
        break;
      }
      case "toggle-unit": {
        S.units = S.units.map((u) => u.id === ds.id ? { ...u, status: u.status === "active" ? "disabled" : "active" } : u);
        dataStore.saveUnits(S.units); render();
        break;
      }
      case "confirm-delete-unit": S.ui.confirmDeleteUnitId = ds.id; render(); break;
      case "cancel-confirm-unit": S.ui.confirmDeleteUnitId = null; render(); break;
      case "delete-unit": {
        S.units = S.units.filter((u) => u.id !== ds.id);
        delete S.reports[ds.id];
        dataStore.saveUnits(S.units); dataStore.deleteReport(ds.id);
        S.ui.confirmDeleteUnitId = null; render();
        break;
      }

      /* ---------- indicators management ---------- */
      case "add-indicator-def": {
        const form = readIndicatorDefForm("new-ind");
        if (!form.name.trim()) break;
        S.indicatorDefinitions = [...S.indicatorDefinitions, { id: uid("ind"), ...form, name: form.name.trim() }];
        dataStore.saveIndicatorDefinitions(S.indicatorDefinitions);
        S.ui.newIndicatorForm = {};
        render();
        break;
      }
      case "start-indicator-edit": S.ui.editingIndicatorId = ds.id; render(); break;
      case "cancel-indicator-edit": S.ui.editingIndicatorId = null; render(); break;
      case "save-indicator-edit": {
        const form = readIndicatorDefForm("edit-ind");
        if (!form.name.trim()) break;
        S.indicatorDefinitions = S.indicatorDefinitions.map((d) => d.id === ds.id ? { ...d, ...form, name: form.name.trim() } : d);
        dataStore.saveIndicatorDefinitions(S.indicatorDefinitions);
        S.ui.editingIndicatorId = null; render();
        break;
      }
      case "confirm-delete-indicator": S.ui.confirmDeleteIndicatorId = ds.id; render(); break;
      case "cancel-confirm-indicator": S.ui.confirmDeleteIndicatorId = null; render(); break;
      case "delete-indicator-def": {
        S.indicatorDefinitions = S.indicatorDefinitions.filter((d) => d.id !== ds.id);
        dataStore.saveIndicatorDefinitions(S.indicatorDefinitions);
        S.ui.confirmDeleteIndicatorId = null; render();
        break;
      }
      case "load-sample-data": {
        const merged = [...S.indicatorDefinitions];
        SAMPLE_INDICATOR_DEFINITIONS.forEach((def) => { if (!merged.some((d) => d.name === def.name)) merged.push({ id: `ind-sample-${def.name}`, ...def }); });
        S.indicatorDefinitions = merged; dataStore.saveIndicatorDefinitions(merged);
        const targetUnit = S.units.find((u) => u.id === "seed-1") || S.units[0];
        if (targetUnit) {
          const existing = S.reports[targetUnit.id] || dataStore.getReport(targetUnit.id);
          const updated = { ...existing, sections: { ...existing.sections, kpi: { status: "draft", data: { indicators: buildSampleKPIRows(), notes: existing.sections?.kpi?.data?.notes || "" }, updatedAt: Date.now() } },
            indicatorHistory: { ...existing.indicatorHistory, ...buildSampleIndicatorHistory() } };
          saveReportNow(targetUnit.id, updated);
        }
        S.ui.sampleStatus = "تم تحميل البيانات التجريبية ✓";
        render();
        setTimeout(() => { S.ui.sampleStatus = ""; if (S.view === "indicators-manage") render(); }, 2500);
        break;
      }

      /* ---------- goals management (strategic/operational share the same actions via prefix) ---------- */
      case "add-strategic-goal": case "add-operational-goal": {
        const kind = action === "add-strategic-goal" ? "strategic" : "operational";
        const inputEl = document.getElementById(`new-${kind}-goal`);
        const name = (inputEl.value || "").trim();
        if (!name) break;
        const list = S.goalsDefinitions[kind] || [];
        if (!list.some((g) => g.name === name)) {
          S.goalsDefinitions = { ...S.goalsDefinitions, [kind]: [...list, { id: uid(kind[0] + "g"), name }] };
          dataStore.saveGoalsDefinitions(S.goalsDefinitions);
        }
        render();
        break;
      }
      default: handleDynamicGoalAction(action, ds) || handleReportEditorAction(action, ds, e) ;
    }
  });
}

function handleDynamicGoalAction(action, ds) {
  const m = action.match(/^(start|save|cancel|confirm-delete|delete|cancel-confirm)-(Strategic|Operational)-goal(-edit)?$/);
  if (!m) return false;
  const op = m[1], kindLabel = m[2];
  const kind = kindLabel === "Strategic" ? "strategic" : "operational";
  const listKey = kind;
  if (op === "start") { S.ui[`editing${kindLabel}Id`] = ds.id; S.ui[`edit${kindLabel}Value`] = ds.name; render(); return true; }
  if (op === "cancel") { S.ui[`editing${kindLabel}Id`] = null; render(); return true; }
  if (op === "save") {
    const val = document.getElementById(`edit-${kind}-goal-name`).value.trim();
    if (val) {
      S.goalsDefinitions = { ...S.goalsDefinitions, [listKey]: (S.goalsDefinitions[listKey] || []).map((g) => g.id === ds.id ? { ...g, name: val } : g) };
      dataStore.saveGoalsDefinitions(S.goalsDefinitions);
    }
    S.ui[`editing${kindLabel}Id`] = null; render(); return true;
  }
  if (op === "confirm-delete") { S.ui[`confirm${kindLabel}DeleteId`] = ds.id; render(); return true; }
  if (op === "cancel-confirm") { S.ui[`confirm${kindLabel}DeleteId`] = null; render(); return true; }
  if (op === "delete") {
    S.goalsDefinitions = { ...S.goalsDefinitions, [listKey]: (S.goalsDefinitions[listKey] || []).filter((g) => g.id !== ds.id) };
    dataStore.saveGoalsDefinitions(S.goalsDefinitions);
    S.ui[`confirm${kindLabel}DeleteId`] = null; render(); return true;
  }
  return false;
}

/* =============================== Report editor + misc action handlers ========= */
function handleReportEditorAction(action, ds) {
  switch (action) {
    case "toggle-login-pw": S.ui.loginShowPw = !S.ui.loginShowPw; render(); return true;

    case "toggle-phase": S.openPhaseId = S.openPhaseId === ds.phase ? null : ds.phase; render(); return true;
    case "toggle-phase-collapse": S.phaseCollapsed = !S.phaseCollapsed; render(); return true;
    case "open-mobile-phase-sidebar": S.mobilePhaseOpen = true; render(); return true;
    case "close-mobile-phase-sidebar": S.mobilePhaseOpen = false; render(); return true;
    case "select-section": openSection(ds.section); return true;
    case "close-section": {
      // Autosave current progress as a draft (without changing completed flag) before leaving.
      if (S.activeSectionId) persistSection(S.activeSectionId, S.sectionDraft, S.sectionCompleted ? "completed" : "draft");
      closeSection();
      return true;
    }
    case "toggle-section-completed": {
      const next = !S.sectionCompleted;
      if (trySaveSectionWithStatus(next ? "completed" : "draft")) S.sectionCompleted = next;
      render();
      return true;
    }
    case "section-save-draft": {
      if (trySaveSectionWithStatus(S.sectionCompleted ? "completed" : "draft")) {
        S.sectionSaveStatus = "تم الحفظ ✓";
        render();
        setTimeout(() => { S.sectionSaveStatus = ""; if (S.activeSectionId) render(); }, 1500);
      } else render();
      return true;
    }
    case "section-prev": {
      if (!trySaveSectionWithStatus(S.sectionCompleted ? "completed" : "draft")) { render(); return true; }
      const idx = SECTIONS.findIndex((s) => s.id === S.activeSectionId);
      if (idx > 0) openSection(SECTIONS[idx - 1].id);
      return true;
    }
    case "section-next": {
      if (!trySaveSectionWithStatus(S.sectionCompleted ? "completed" : "draft")) { render(); return true; }
      const idx = SECTIONS.findIndex((s) => s.id === S.activeSectionId);
      if (idx < SECTIONS.length - 1) openSection(SECTIONS[idx + 1].id);
      return true;
    }

    /* ---- repeatable items ---- */
    case "add-item": {
      const factory = EMPTY_ITEM_FACTORY[ds.arr];
      if (factory) getItemList(ds.arr).push(factory());
      render();
      return true;
    }
    case "remove-item": {
      const list = S.sectionDraft[ds.arr];
      if (list) S.sectionDraft[ds.arr] = list.filter((x) => x.id !== ds.id);
      render();
      return true;
    }
    case "add-strength": {
      const list = getItemList("strengths");
      if (list.length < 5) list.push(EMPTY_ITEM_FACTORY.strengths());
      render();
      return true;
    }
    case "add-goal": { getItemList("goals").push(EMPTY_ITEM_FACTORY.goals()); render(); return true; }
    case "add-indicator": { getItemList("indicators").push(EMPTY_ITEM_FACTORY.indicators()); render(); return true; }

    /* ---- indicator card toggles ---- */
    case "toggle-indicator-details": {
      S.ui.indicatorDetailsOpen = S.ui.indicatorDetailsOpen || {};
      S.ui.indicatorDetailsOpen[ds.id] = !S.ui.indicatorDetailsOpen[ds.id];
      render(); return true;
    }
    case "toggle-indicator-editing": {
      S.ui.indicatorEditingOpen = S.ui.indicatorEditingOpen || {};
      S.ui.indicatorEditingOpen[ds.id] = !S.ui.indicatorEditingOpen[ds.id];
      render(); return true;
    }
    case "submit-new-indicator": {
      const key = `newIndicatorForm_${ds.id}`;
      const form = S.ui[key] || {};
      if (!(form.name && form.name.trim() && form.target !== "" && form.target !== undefined)) { render(); return true; }
      const name = form.name.trim();
      if (!S.indicatorDefinitions.some((d) => d.name === name)) {
        S.indicatorDefinitions = [...S.indicatorDefinitions, { id: uid("ind"), name, category: "", direction: "", unit: "", ...form }];
        dataStore.saveIndicatorDefinitions(S.indicatorDefinitions);
      }
      const list = getItemList("indicators");
      const item = findById(list, ds.id);
      if (item) item.name = name;
      delete S.ui[key];
      render(); return true;
    }
    case "cancel-new-indicator": {
      const list = getItemList("indicators");
      const item = findById(list, ds.id);
      if (item) item.name = "";
      delete S.ui[`newIndicatorForm_${ds.id}`];
      render(); return true;
    }

    /* ---- expandable "other" select ---- */
    case "add-expandable-option": {
      const otherKey = ds.key;
      const val = ((S.ui.expandableOtherText && S.ui.expandableOtherText[otherKey]) || "").trim();
      if (!val) { render(); return true; }
      const arr = ds.arr || null, id = ds.id || null, subarr = ds.subarr || null, subid = ds.subid || null, field = ds.field;
      const mapKey = `${arr || "top"}|${field}`;
      const customArrKey = CUSTOM_OPTION_FIELD_MAP[mapKey];
      if (customArrKey) {
        const existing = S.sectionDraft[customArrKey] || [];
        if (!existing.includes(val)) S.sectionDraft[customArrKey] = [...existing, val];
      }
      // set the value itself using the same addressing scheme as any bound field
      setFieldFromEl({ dataset: { arr, id, field, subarr, subid }, value: val });
      if (S.ui.expandableOtherText) delete S.ui.expandableOtherText[otherKey];
      render(); return true;
    }

    /* ---- multi-select dropdown (goals -> operational goals) ---- */
    case "toggle-multi-dropdown": S.ui.openMultiDropdown = S.ui.openMultiDropdown === ds.key ? null : ds.key; render(); return true;
    case "multi-toggle": {
      // key format: goal-og-<goalId>
      const m = ds.key.match(/^goal-og-(.+)$/);
      if (!m) return true;
      const goalId = m[1];
      const list = getItemList("goals");
      const goal = findById(list, goalId);
      if (!goal) return true;
      const existing = goal.operationalGoals || [];
      const has = existing.some((og) => og.name === ds.value);
      if (has) {
        goal.operationalGoals = existing.filter((og) => og.name !== ds.value);
      } else {
        goal.operationalGoals = [...existing, { id: uid("og"), name: ds.value, level: "", percentage: "", evidenceType: "", evidenceAnswer: "", explanation: "" }];
      }
      render(); return true;
    }
  }
  return false;
}

function trySaveSectionWithStatus(status) {
  if (S.activeSectionId === "goals") {
    const result = validateGoalsData(S.sectionDraft);
    if (!result.valid) { S.sectionSaveError = result.message; return false; }
  }
  S.sectionSaveError = "";
  persistSection(S.activeSectionId, S.sectionDraft, status);
  return true;
}

/* =============================== After-render hook + bootstrap ================ */
function afterRender() {
  const loginUserEl = document.getElementById("login-username");
  if (loginUserEl) loginUserEl.focus();
}

function boot() {
  attachFormListeners();
  attachClickListener();
  render();
}

document.addEventListener("DOMContentLoaded", boot);
